css:
.tour-container {
  font-family: Arial, sans-serif;
  color: #222;
  width: 100%;
}

.header {
  border-bottom: 1px solid #e0e0e0;
  text-align: center;
  padding: 20px 0;
}

.logo {
  width: 130px;
  margin-bottom: 10px;
}

.title {
  text-align: center;
  font-size: 24px;
  font-weight: 600;
  margin-top: 24px;
}

.subtitle {
  text-align: center;
  color: #555;
  max-width: 700px;
    margin-top: 10px;
  margin-right:auto ;
  margin-left:auto ;
  line-height: 1.5;
}

.summary {
  display: flex;
  width: 100%;
  justify-content: space-between;
  margin: 30px 0;
}

.summary-box {
  border: 1px solid #ddd;
  width: 23%;
  border-radius: 6px;
  text-align: center;
  padding: 16px;
}

.summary-box .label {
  font-size: 14px;
  color: #666;
}

.summary-box .value {
  font-size: 20px;
  margin-top: 8px;
  font-weight: 500;
}

.day-card {
  border: 1px solid #ddd;
  border-radius: 6px;
  margin: 40px 0;
  overflow: hidden;
  page-break-inside: avoid;
}

.day-image {
  width: 100%;
  height: 320px;
  object-fit: cover;
}

.day-content {
  padding: 24px;
}

.day-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.day-label {
  background: #030213;
  color: white;
  padding: 8px 12px;
  border-radius: 4px;
  font-weight: 500;
}

.difficulty {
  background: #c8f7c5;
  color: #0c5b0c;
  font-size: 14px;
  border-radius: 20px;
  padding: 4px 10px;
}

.day-title {
  font-size: 22px;
  margin-top: 20px;
}

.destination {
  margin-top: 20px;
}

.destination-header {
  display: flex;
  align-items: center;
  gap: 6px;
}

.destination h3 {
  margin: 0;
  font-size: 16px;
}

.destination p {
  color: #555;
  margin-top: 6px;
}

.notes {
  background: #f2f2f2;
  padding: 16px;
  border-radius: 8px;
  margin-top: 20px;
}

.notes-header {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 8px;
}

.notes ul {
  margin: 0;
  padding-left: 18px;
  color: #444;
  font-size: 14px;
}

.attractions {
  margin-top: 20px;
}

.attractions h4 {
  margin-bottom: 10px;
}

.attractions-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}

.chip {
  background: #f0f0f0;
  padding: 6px 10px;
  border-radius: 6px;
  font-size: 14px;
}

.chip span {
  color: #666;
  margin-left: 4px;
}

.activities {
  margin-top: 20px;
}

.activities-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 12px;
}

.activity-name {
  font-weight: 500;
}

.activity-desc {
  font-size: 14px;
  color: #666;
  margin-top: 4px;
}

.travel {
  border-top: 1px solid #ddd;
  margin-top: 20px;
  padding-top: 20px;
}

.travel h4 {
  font-size: 14px;
  margin-bottom: 12px;
}

.travel-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 12px 24px;
  font-size: 14px;
}

.travel-grid div {
  display: flex;
  align-items: center;
  gap: 6px;
}

.icon {
  font-size: 14px;
}
